   110	    }
   111	
   112	    public String generate(YearMonth month) {
   113	        List<Reservation> taxed = new ArrayList<>();
   114	        for (Reservation reservation : store.all()) {
   115	            if (reservation.isPaid() && YearMonth.from(reservation.checkIn()).equals(month)) {
   116	                taxed.add(reservation);
   117	            }
   118	        }
   119	        taxed.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
